ALTER TABLE public.students ADD COLUMN IF NOT EXISTS email text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS location text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS profile_photo_path text, ADD COLUMN IF NOT EXISTS cv_path text;
ALTER TABLE public.organizations ADD COLUMN IF NOT EXISTS email text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS phone text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS address text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS city text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS linkedin_url text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS established_year integer;
CREATE TABLE public.admin_audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, entity text NOT NULL, record_id uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit_log TO authenticated;
GRANT ALL ON public.admin_audit_log TO service_role;
ALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "super admin reads audit" ON public.admin_audit_log FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'super_admin'));
CREATE OR REPLACE FUNCTION public.audit_admin_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.has_role(auth.uid(),'super_admin') THEN INSERT INTO public.admin_audit_log(actor_id,entity,record_id,action) VALUES(auth.uid(),TG_TABLE_NAME,COALESCE(NEW.id,OLD.id),TG_OP); END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER students_admin_audit AFTER INSERT OR UPDATE OR DELETE ON public.students FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER organizations_admin_audit AFTER INSERT OR UPDATE OR DELETE ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER postings_admin_audit AFTER INSERT OR UPDATE OR DELETE ON public.postings FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER applications_admin_audit AFTER INSERT OR UPDATE OR DELETE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE OR REPLACE FUNCTION public.guard_student_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'super_admin') AND NOT (NEW.institution_id IS NOT NULL AND public.is_institution_admin(auth.uid(),NEW.institution_id)) THEN IF TG_OP='INSERT' THEN NEW.verified:=false; ELSE NEW.verified:=OLD.verified; NEW.placement_status:=OLD.placement_status; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER student_verification_guard BEFORE INSERT OR UPDATE ON public.students FOR EACH ROW EXECUTE FUNCTION public.guard_student_verification();
CREATE OR REPLACE FUNCTION public.guard_application_integrity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.stage<2 OR NEW.stage>11 THEN RAISE EXCEPTION 'Invalid journey stage'; END IF; IF TG_OP='UPDATE' AND (NEW.student_id IS DISTINCT FROM OLD.student_id OR NEW.posting_id IS DISTINCT FROM OLD.posting_id) THEN RAISE EXCEPTION 'Application ownership cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER application_integrity_guard BEFORE INSERT OR UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.guard_application_integrity();
CREATE POLICY "profile files owner insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='profile-files' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "profile files authorized read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='profile-files' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM public.students s WHERE (s.cv_path=name OR s.profile_photo_path=name) AND public.org_sees_student(auth.uid(),s.id)) OR EXISTS(SELECT 1 FROM public.organizations o WHERE o.logo_url=name AND o.approved)));
CREATE POLICY "profile files owner delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='profile-files' AND (storage.foldername(name))[1]=auth.uid()::text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.students,public.organizations,public.postings,public.applications TO authenticated;